/// Bead `sts2-rs-346jo`: spot-check the `CardId` → `CardTags`
/// mapping is wired into `card_from_spec`. Covers every tag
/// family. Untagged cards (Bash etc.) round-trip to NONE.
#[test]
fn card_from_spec_applies_canonical_tags() {
    use super::super::ironclad_basic::{defend, strike};
    let s = card_from_spec(&strike());
    assert!(s.has_tag(CardTag::Strike), "Strike → Strike tag");
    assert!(!s.has_tag(CardTag::Defend));
    let d = card_from_spec(&defend());
    assert!(d.has_tag(CardTag::Defend), "Defend → Defend tag");
    assert!(!d.has_tag(CardTag::Strike));
    // Spot every tag family via tags_for_card_id directly
    // (avoids needing every spec factory imported here).
    assert!(tags_for_card_id(CardId::Shiv).contains(CardTag::Shiv));
    assert!(tags_for_card_id(CardId::MinionDiveBomb).contains(CardTag::Minion));
    assert!(tags_for_card_id(CardId::HighFive).contains(CardTag::OstyAttack));
    assert!(tags_for_card_id(CardId::PerfectedStrike).contains(CardTag::Strike));
    assert!(tags_for_card_id(CardId::UltimateDefend).contains(CardTag::Defend));
    // An untagged content card.
    assert_eq!(tags_for_card_id(CardId::Bash), CardTags::NONE);
}

