/// Inky-enchanted Shiv (every Shiv generated by Blade of Ink — C#
/// `BladeOfInk.cs:36` `CardCmd.Enchant<Inky>`) deals `+1` damage (v0.107.1;
/// was `+2`) and applies
/// `1` Weak to the target on play (`Inky.cs` `EnchantDamageAdditive` +
/// `OnPlay`). A plain Shiv does neither. Pins the Silent-sweep
/// `MONSTER_STATE|card:BLADE_OF_INK` fix (seed 11: `monsters[1].hp` cs43/rs45,
/// `monsters[1].powers.len` cs1/rs0).
#[test]
fn play_shiv_inky_adds_damage_and_weak() {
    use std::num::NonZeroU32;
    use sts2_core::cards::{Card, CardType, EnchantmentId, TargetType};
    use sts2_core::{Creature, IntentHistory, MonsterId, MonsterKind, PowerKind};
    install_pool();

    let enemy_weak = |state: &CombatState| -> Option<i32> {
        state.creatures[0].powers.iter().find_map(|pu| {
            state
                .powers
                .iter()
                .find(|p| p.id == pu.0 && p.kind == PowerKind::Weak)
                .map(|p| p.amount)
        })
    };

    let play = |inky: bool| -> CombatState {
        let mut state = CombatState::default();
        let enemy_id = NonZeroU32::new(1).expect("nz");
        state.creatures.push(Creature {
            id: enemy_id,
            current_hp: 100,
            max_hp: 100,
            block: 0,
            powers: smallvec::SmallVec::new(),
            species: Some(MonsterKind::Nibbit),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: MonsterId("Nibbit"),
            ai: None,
        });
        let euid = CreatureUid(enemy_id);
        state.enemy_uids.push(euid);
        let card_uid = NonZeroU32::new(1).expect("nz");
        let mut card = Card {
            uid: CardUid(card_uid),
            card_id: CardId::Shiv,
            cost: sts2_core::CardEnergyCost::new(0),
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 4,
            base_block: 0,
            ..Card::pod_defaults()
        };
        if inky {
            card.set_enchantment(EnchantmentId::Inky, 1);
        }
        state.cards.push(card);
        state.player.play.push(CardUid(card_uid));
        let f = lookup(CardId::Shiv).expect("registered");
        f(&mut state, Some(euid));
        state
    };

    let plain = play(false);
    assert_eq!(
        plain.creatures[0].current_hp, 96,
        "plain Shiv deals 4 (100 - 4)"
    );
    assert_eq!(enemy_weak(&plain), None, "plain Shiv applies no Weak");

    let inky = play(true);
    assert_eq!(
        inky.creatures[0].current_hp, 95,
        "Inky Shiv deals 4 + 1 = 5 (100 - 5)"
    );
    assert_eq!(enemy_weak(&inky), Some(1), "Inky Shiv applies 1 Weak");
}

