/// GH #335: an untargeted Shiv whose FanOfKnives has lapsed between the moment
/// the untargeted action was surfaced and the moment the effect runs must NOT
/// abort the process. `play_shiv` used to `expect("Shiv: Enemy-targeted")`
/// here; a PyO3 `PanicException` is a `BaseException`, so it escaped the
/// Python worker guards and killed the whole worker process (~1 in 9,200 runs
/// on the #333 Silent PPO campaign). The AoE arm is what surfaced the
/// untargeted play, so resolving it is the faithful completion.
#[test]
fn play_shiv_untargeted_without_fan_of_knives_resolves_aoe() {
    use std::num::NonZeroU32;
    use sts2_core::cards::{Card, CardType, TargetType};
    use sts2_core::{Creature, IntentHistory, MonsterId, MonsterKind, PowerKind};
    install_pool();

    let mut state = CombatState::default();
    for i in 1..=2u32 {
        let enemy_id = NonZeroU32::new(i).expect("nz");
        state.creatures.push(Creature {
            id: enemy_id,
            current_hp: 100,
            max_hp: 100,
            block: 0,
            powers: smallvec::SmallVec::new(),
            species: Some(MonsterKind::Nibbit),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: MonsterId("Nibbit"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid(enemy_id));
    }
    let card_uid = NonZeroU32::new(1).expect("nz");
    state.cards.push(Card {
        uid: CardUid(card_uid),
        card_id: CardId::Shiv,
        cost: sts2_core::CardEnergyCost::new(0),
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage: 4,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.play.push(CardUid(card_uid));

    // Precondition: the power is GONE — this is exactly the state that used to
    // panic, since `legal_actions` had surfaced the play while it was active.
    assert_eq!(state.player_power_amount(PowerKind::FanOfKnives), 0);
    assert!(!sts2_core::cards::shiv_hits_all_enemies(&state));

    let f = lookup(CardId::Shiv).expect("registered");
    assert_eq!(f(&mut state, None), EffectResult::Resolved);

    for c in &state.creatures {
        assert_eq!(c.current_hp, 96, "untargeted Shiv resolves the AoE arm");
    }
}

