/// Slimed = cost-1, EXHAUST, draws 1 card on play. Test confirms cost +
/// EXHAUST keyword + that play_slimed runs `cards::draw(1)` on the
/// player. The EXHAUST itself is applied by the combat loop.
#[test]
fn slimed_costs_1_and_exhausts() {
    use std::num::NonZeroU32;
    install_pool();
    let s = specs::slimed();
    assert_eq!(s.cost, 1);
    assert!(s
        .keywords
        .contains(super::super::types::CardKeywords::EXHAUST));
    // Play on empty draw — no panic, no draw.
    let mut empty_state = CombatState::default();
    let r = play_slimed(&mut empty_state, None);
    assert_eq!(r, EffectResult::Resolved);
    // Play with 3 cards in draw — hand grows by 1.
    let mut state = CombatState::default();
    // A live player: a dead one makes the combat ending, so draws move no card.
    state.player.current_hp = 80;
    for n in 1..=3u32 {
        state
            .player
            .draw
            .push(CardUid(NonZeroU32::new(n).expect("nz")));
    }
    let hand_before = state.player.hand.len();
    let draw_before = state.player.draw.len();
    let _ = play_slimed(&mut state, None);
    assert_eq!(state.player.hand.len(), hand_before + 1);
    assert_eq!(state.player.draw.len(), draw_before - 1);
}

