// ─── Bead `sts2-rs-8z3fl.14` — VOID two-hook end-to-end parity ─────
//
// Void's behaviour at the Python pin (`cards/status.py:183-189`
// for the spec + `:1391-1407` for the two hooks) is:
//   (a) `register_after_card_drawn_hook(CardId.VOID)` —
//       fires on draw; calls `combat.lose_energy(owner, energy=1)`.
//   (b) keyword `ethereal` — at end-of-turn cleanup
//       (`core/combat.py:992-999`), an Ethereal card in hand is
//       moved to the exhaust pile.
//
// Existing tests cover (a) in `sts2-core` (drawing_void_drains_…)
// and (b)'s registry shape in `void_is_unplayable_ethereal` above.
// This test exercises BOTH hooks end-to-end in a single fixture
// matching the bead's "setup hand=[Void] → energy 3→2 → end_turn →
// Void in exhaust, hand=0" shape.

/// Void draws drain 1 energy then end-of-turn ethereal expel sends
/// Void to exhaust. Pin:
/// `sts2-rl-agent@01c094d:sts2_env/cards/status.py:183-189` (spec)
/// + `:1391-1407` (hooks)
/// + `core/combat.py:992-999` (ethereal sweep).
#[test]
fn void_drawn_energy_loss_then_end_of_turn_ethereal_expel() {
    use std::num::NonZeroU32;
    use sts2_core::cards::{CardId, CardType, TargetType};
    use sts2_core::combat_loop::{end_player_turn_phase_one, end_player_turn_phase_two};
    use sts2_core::{Card, CardUid, CombatPhase, CombatState};

    // Install the card-keyword registry so the ETHEREAL keyword
    // lookup at end-of-turn resolves true for `CardId::Void`.
    crate::cards::dispatch::install_default_registry();
    install_pool();

    let mut state = CombatState::default();
    // Live combat: end_player_turn_phase_one's step 3 now runs the full
    // `check_combat_end` (C# CheckWinCondition), so a default hp-0 player
    // (or an enemy-less arena) would short-circuit as CombatLost/Won
    // before the ethereal expel under test.
    state.player.current_hp = 70;
    state.player.max_hp = 70;
    let _ = state.init_player_creature();
    let enemy_id = NonZeroU32::new(900).expect("nz");
    state.creatures.push(sts2_core::Creature {
        id: enemy_id,
        current_hp: 50,
        max_hp: 50,
        block: 0,
        powers: smallvec::SmallVec::new(),
        species: Some(sts2_core::MonsterKind::Nibbit),
        intent: None,
        intent_history: sts2_core::IntentHistory::default(),
        monster_id: sts2_core::MonsterId("Nibbit"),
        ai: None,
    });
    state.enemy_uids.push(sts2_core::CreatureUid(enemy_id));
    state.phase = CombatPhase::PlayerPlayPhase;
    state.player.energy = 3;

    // Seed a Void into the draw pile, then draw 1 to land it in
    // hand and fire the after-card-drawn hook (energy drain).
    let void_uid = state.add_card_to_draw_pile(Card {
        uid: CardUid(NonZeroU32::new(u32::MAX).expect("nz placeholder")),
        card_id: CardId::Void,
        cost: sts2_core::CardEnergyCost::new(-1),
        card_type: CardType::Status,
        target_type: TargetType::None,
        upgraded: false,
        base_damage: 0,
        base_block: 0,
        ..Card::pod_defaults()
    });
    let drawn = state.draw_into_hand(1);
    assert_eq!(drawn, 1, "Void drawn into hand");
    assert!(
        state.player.hand.contains(&void_uid),
        "Void uid present in hand pile"
    );

    // Hook (a): drawn-energy-loss.
    assert_eq!(
        state.player.energy, 2,
        "Void.after_card_drawn must drain 1 energy on draw \
             (Python pin status.py:1398-1406)"
    );

    // Run the canonical player end-turn pipeline. Ethereal expel
    // happens in phase_two (per the inline comment block at
    // combat_loop.rs:735-740).
    end_player_turn_phase_one(&mut state);
    end_player_turn_phase_two(&mut state);

    // Hook (b): ethereal expel — Void must have moved hand → exhaust.
    assert!(
        !state.player.hand.contains(&void_uid),
        "Void must have left the hand after the ethereal expel"
    );
    assert!(
        state.player.exhaust.contains(&void_uid),
        "Void must land in the exhaust pile (not discard) per ETHEREAL"
    );
    assert_eq!(
        state.player.hand.len(),
        0,
        "hand is empty post-expel (Void was the only card)"
    );
}

/// Luminesce grants `EnergyVar` energy — **2 base / 3 upgraded**.
/// C# `../sts2-wiki/decompiled/v0.107.1/MegaCrit.Sts2.Core.Models.Cards/Luminesce.cs:13`
/// (`CanonicalVars = EnergyVar(2)`), `:31` (`GainEnergy(Energy.BaseValue)`),
/// `:36` (`OnUpgrade → Energy.UpgradeValueBy(1m)`). The prior port hard-coded
/// 2 from the Python sim, which has no upgrade branch; upgraded Luminesces are
/// live content (Radiant Pearl spawns them, Jewelry Box's Apotheosis upgrades
/// them) and the mirror ran 1 energy low for the rest of the turn.
#[test]
fn play_luminesce_grants_two_energy_three_when_upgraded() {
    use std::num::NonZeroU32;
    use sts2_core::cards::{Card, CardType, TargetType};
    install_pool();

    let gained = |upgraded: bool| -> i32 {
        let mut state = CombatState::default();
        let card_uid = NonZeroU32::new(1).expect("nz");
        state.cards.push(Card {
            uid: CardUid(card_uid),
            card_id: CardId::Luminesce,
            cost: sts2_core::CardEnergyCost::new(0),
            card_type: CardType::Skill,
            target_type: TargetType::Self_,
            upgraded,
            base_damage: 0,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.play.push(CardUid(card_uid));
        let before = state.player.energy;
        let f = lookup(CardId::Luminesce).expect("registered");
        f(&mut state, None);
        state.player.energy - before
    };

    assert_eq!(gained(false), 2, "unupgraded Luminesce → EnergyVar(2)");
    assert_eq!(
        gained(true),
        3,
        "upgraded Luminesce → 2 + UpgradeValueBy(1)"
    );
}

/// `Inky.OnPlay` (Inky.cs) runs after `Shiv.OnPlay` and, for an `AllEnemies`
/// card (a Shiv under Fan of Knives), reads `CombatState.HittableEnemies` at
/// that point. A Shiv that kills an Infested enemy spawns its four Wrigglers
/// inside the hit (`InfestedPower.AfterDeath`), so the Weak lands on them.
/// Rust used the enemy list snapshotted before the damage and gave the
/// Wrigglers nothing (loadout Silent 7030 v0.107.1).
#[test]
fn fan_of_knives_inky_shiv_weakens_wrigglers_spawned_by_its_kill() {
    use std::num::NonZeroU32;
    use sts2_core::cards::{Card, CardType, EnchantmentId, TargetType};
    use sts2_core::{
        CombatPhase, Creature, IntentHistory, MonsterId, MonsterKind, Power, PowerKind, PowerUid,
    };
    install_pool();
    crate::cards::dispatch::ensure_installed();

    let mut state = CombatState::default();
    let enemy_id = NonZeroU32::new(1).expect("nz");
    state.creatures.push(Creature {
        id: enemy_id,
        current_hp: 1,
        max_hp: 61,
        block: 0,
        powers: smallvec::SmallVec::new(),
        species: Some(MonsterKind::PhrogParasite),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("PhrogParasite"),
        ai: None,
    });
    state.enemy_uids.push(CreatureUid(enemy_id));
    state.player.current_hp = 80;
    state.player.max_hp = 80;
    state.player.energy = 3;
    state.player.max_energy = 3;
    let _ = state.init_player_creature();
    state.phase = CombatPhase::PlayerPlayPhase;
    let infested = NonZeroU32::new(7700).expect("nz");
    state
        .powers
        .push(Power::new(infested, PowerKind::Infested, 4));
    state.creatures[0].powers.push(PowerUid(infested));
    let fan = NonZeroU32::new(7701).expect("nz");
    state
        .powers
        .push(Power::new(fan, PowerKind::FanOfKnives, 1));
    state.player.powers.push(PowerUid(fan));

    let card_uid = CardUid(NonZeroU32::new(1).expect("nz"));
    let mut card = Card {
        uid: card_uid,
        card_id: CardId::Shiv,
        cost: sts2_core::CardEnergyCost::new(0),
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage: 4,
        base_block: 0,
        ..Card::pod_defaults()
    };
    card.set_enchantment(EnchantmentId::Inky, 1);
    state.cards.push(card);
    state.player.hand.push(card_uid);

    let _ = sts2_core::combat_loop::play_card(&mut state, 0, None);

    let wrigglers: Vec<&Creature> = state
        .creatures
        .iter()
        .filter(|c| c.species == Some(MonsterKind::Wriggler) && c.current_hp > 0)
        .collect();
    assert_eq!(wrigglers.len(), 4, "the kill spawned four Wrigglers");
    for w in wrigglers {
        let weak = w.powers.iter().find_map(|pu| {
            state
                .powers
                .iter()
                .find(|p| p.id == pu.0 && p.kind == PowerKind::Weak)
                .map(|p| p.amount)
        });
        assert_eq!(weak, Some(1), "Inky weakens every spawned Wriggler");
    }
}
